lab.solution:
from flask import Flask
import sys

app = Flask(__name__)

@app.get('/health')
def health():
    return {'status': 'ok'}

response = app.test_client().get('/health')
assert response.status_code == 200
assert response.json == {'status': 'ok'}
print('in-process health test passed')

if __name__ == '__main__' and '--local-preview' in sys.argv:
    # Trusted local development only.
    app.run(debug=False)
